import { bindJoystick } from './joystick.js';
import { restoreFlood } from './flood-systems.js';
import { createExpedition } from './flood-expedition.js';
import { createRenderLoop, createAudioController } from './runtime.js';
import { SURVIVAL_UPGRADES, restoreTraining, trainingCost, buyTraining, survivalBenefits } from './survival-upgrades.js';
import './style.css';
import * as T from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { districts,makeMaterials,buildDistrict,loadCharacters,rifle,atmosphere } from './assets.js';
import { initStorage,loadSave,saveProgress,CooperativeRoom } from './services.js';
import { withinExpansion,siteNames } from './expansion.js';

const controls={sensitivity:1,invert:false,shoulder:1,zoom:4.9,quality:'high',flashlight:false};
const velocity=new T.Vector2();
let moveStick={x:0,y:0},lookStick={x:0,y:0};const joysticks=[];
let insideSite=null;

const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s);
const defaults=()=>({version:1,flood:restoreFlood(),training:restoreTraining(),day:1,time:17.5,hp:100,hunger:100,ammo:30,reserve:120,medkits:3,scrap:15,credits:0,xp:0,kills:0,looted:0,missions:[],visited:[0],achievements:[],lastReward:'',streak:0,challengeDate:'',dailyKills:0,dailyLoot:0,dailyClaimed:false,upgrade:0,jobs:0,district:0,cacheProgress:[0,0,0,0],jobProgress:0,depleted:[[],[],[],[]],supplyDay:1,lastSecured:[-1,-1,-1,-1],position:{x:0,z:38},sound:true});
let state=defaults(),stamina=100,running=false,modalOpen=false,ready=false,world=null,actor=null,characters=null,currentDistrict=0,elapsed=0,autosave=0,enemySpawnClock=0,netClock=0,hudClock=0,lastShot=-2,reloadUntil=0,invulnerable=0,shootUntil=0,dodgeUntil=0,mouseDown=false,aiming=false,dragging=false,yaw=0,pitch=0,dead=false,toastTimer=0;
const keys=new Set(),enemies=[],remotes=new Map(),effects=[];
let activeTab='missions',selectedDistrict=0;
const renderer=new T.WebGLRenderer({canvas:$('#world'),antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.02;renderer.setSize(innerWidth,innerHeight);
const scene=new T.Scene();scene.fog=new T.FogExp2(0xa5ad93,.0095);const camera=new T.PerspectiveCamera(57,innerWidth/innerHeight,.1,500);camera.position.set(1,4,37);
const materials=makeMaterials(),lighting=atmosphere(scene,renderer);const composer=new EffectComposer(renderer);composer.addPass(new RenderPass(scene,camera));const bloom=new UnrealBloomPass(new T.Vector2(innerWidth,innerHeight),.15,.7,1.35);composer.addPass(bloom);composer.addPass(new OutputPass());
const muzzleLight=new T.PointLight(0xffc570,0,9,2);scene.add(muzzleLight);
const torch=new T.SpotLight(0xe5ecdf,28,24,.38,.55,1.3);torch.visible=false;scene.add(torch,torch.target);
function captureMouse(){if(!document.pointerLockElement){const request=$('#world').requestPointerLock?.();request?.catch(()=>toast('Mouse capture unavailable. Hold right mouse to look.'));}}
function clearInput(){for(const stick of joysticks)stick.reset();keys.clear();velocity.set(0,0);mouseDown=false;aiming=false;dragging=false;}
function colliderBox(c,padding=0){return new T.Box3(new T.Vector3(c.x-c.w/2-padding,c.minY||0,c.z-c.d/2-padding),new T.Vector3(c.x+c.w/2+padding,c.h,c.z+c.d/2+padding));}
const raycaster=new T.Raycaster(),v1=new T.Vector3(),v2=new T.Vector3();
const audio=createAudioController();
const events=new AbortController();
function listen(target,type,handler,options={}){target.addEventListener(type,handler,{...options,signal:events.signal});}
const particles=new T.BufferGeometry();const dots=new Float32Array(600);for(let i=0;i<600;i+=3){dots[i]=(Math.random()-.5)*90;dots[i+1]=Math.random()*15;dots[i+2]=(Math.random()-.5)*120;}particles.setAttribute('position',new T.BufferAttribute(dots,3));const dust=new T.Points(particles,new T.PointsMaterial({color:0xf2d69a,size:.035,transparent:true,opacity:.4,depthWrite:false}));scene.add(dust);

function toast(message){audio.cue();$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function playAudio(){void audio.activate(state.sound);}
function gunAudio(){audio.shot();}
function rank(){return 1+Math.floor(state.xp/400);}
let saveStatusTimer=0;
function showSaveStatus(message){clearTimeout(saveStatusTimer);const display=()=>{$('#save-status').textContent=message;$('#live-save').textContent=message;$('#live-save').dataset.state=message.startsWith('Save failed')?'error':'saved';};if(message.startsWith('Saved'))saveStatusTimer=setTimeout(display,500);else display();}
function save(){if(!ready)return false;if(actor&&running&&!dead)state.position={x:actor.group.position.x,z:actor.group.position.z};state.district=currentDistrict;return saveProgress(structuredClone(state));}
function resetDaily(){const today=new Date().toISOString().slice(0,10);if(state.challengeDate!==today){state.challengeDate=today;state.dailyKills=0;state.dailyLoot=0;state.dailyClaimed=false;}}
function unlock(id){if(state.achievements.includes(id))return;state.achievements.push(id);toast(`Achievement unlocked · ${achievementList.find(a=>a.id===id)?.title||id}`);}
const achievementList=[{id:'first',title:'Still breathing',desc:'Defeat your first infected.',test:()=>state.kills>=1},{id:'scavenge',title:'Waste not',desc:'Search 5 relief caches.',test:()=>state.looted>=5},{id:'signal',title:'A voice in the dark',desc:'Restore a district radio.',test:()=>state.missions.length>=1},{id:'traveler',title:'Roads less traveled',desc:'Visit all four districts.',test:()=>state.visited.length>=4},{id:'hunter',title:'Hold the line',desc:'Defeat 25 infected.',test:()=>state.kills>=25},{id:'survivor',title:'Tomorrow is another day',desc:'Survive into day 2.',test:()=>state.day>=2},{id:'network',title:'Coast to coast',desc:'Restore all four district radios.',test:()=>state.missions.length>=4}];
function checkAchievements(){for(const a of achievementList)if(a.test())unlock(a.id);}
function giveKill(){state.kills++;state.dailyKills++;state.xp+=35;state.scrap+=3;checkAchievements();toast('+35 XP · Infected neutralized · +3 scrap');save();}
function disposeWorld(){if(!world)return;scene.remove(world.root);world.root.traverse(o=>{if(o.isMesh)o.geometry.dispose();});for(const e of enemies)scene.remove(e.actor.group);enemies.length=0;}
function makeEnemy(id,x,z,hp=100){const a=characters.make('infected');a.group.position.set(x,0,z);a.group.rotation.y=Math.PI;scene.add(a.group);const e={id,actor:a,hp,lastAttack:0,target:new T.Vector3(x,0,z),angle:0};enemies.push(e);return e;}
function spawnEnemies(){const positions=[[0,19],[-3,2],[5,-12],[-5,-27],[2,-37],[6,35],[-4,-45]];for(let i=0;i<positions.length;i++)makeEnemy(`d${currentDistrict}-${i}`,currentDistrict===3?positions[i][0]*.3:positions[i][0],positions[i][1],i===0?70:100);}
function applyUsed(items){for(const i of world.interact)if(i.type==='cache'){i.used=items.includes(i.id);i.group.visible=!i.used;}else if(i.type==='radio'&&items.includes(i.id)){i.used=true;i.marker.material=materials.blue;}}
function changeDistrict(index,{remote=false,keepPosition=false}={}){
 if(room.connected&&!room.isHost&&!remote){toast('The room leader chooses the expedition district.');return;}
 disposeWorld();currentDistrict=index;selectedDistrict=index;world=buildDistrict(index,materials);scene.add(world.root);scene.fog.color.set(index===3?0x8b9e8a:0xa5ad93);scene.fog.density=index===3?.017:.0095;
 if(actor){actor.group.position.set(0,0,38);if(keepPosition&&Number.isFinite(state.position?.x)&&Number.isFinite(state.position?.z)&&!collides(state.position.x,state.position.z))actor.group.position.set(state.position.x,0,state.position.z);actor.group.rotation.y=Math.PI;yaw=0;pitch=.015;clearInput();insideSite=null;}
 if(characters&&(!room.connected||room.isHost))spawnEnemies();
 if(!state.visited.includes(index))state.visited.push(index);checkAchievements();
 if(state.missions.includes(index)){const r=world.interact.find(i=>i.type==='radio');r.used=true;r.marker.material=materials.blue;}
 applyUsed([...(state.depleted[index]||[]),...(state.missions.includes(index)?['radio']:[])]);
 expedition.rebuild();updateDistrictUI();if(room.connected&&room.isHost)sendSnapshot();
}
function updateDistrictUI(){const d=districts[currentDistrict];$('#hud-city').textContent=d.name;$('#hud-area').textContent=d.area.toUpperCase();$('#menu-place').textContent=d.area;$('#menu-weather').textContent=`${d.name} · ${d.weather} · Sundown`;$('#menu-region').textContent=['LOUISIANA','TEXAS','CALIFORNIA','LOUISIANA'][currentDistrict];$$('[data-district]').forEach(b=>{b.classList.toggle('selected',+b.dataset.district===currentDistrict);b.innerHTML=districts[+b.dataset.district].name+(+b.dataset.district===currentDistrict?' <span>●</span>':'');});$('#continue-details').textContent=`Day ${state.day} · ${d.name} · Survivor rank ${rank()}`;}
function collides(x,z,r=.42){if(!withinExpansion(currentDistrict,x,z,r))return true;for(const c of world.colliders)if((c.minY||0)<1.8+(currentDistrict===3?.26:0)&&Math.abs(x-c.x)<c.w/2+r&&Math.abs(z-c.z)<c.d/2+r)return true;return false;}
function move(o,dx,dz,r=.42){if(o===actor?.group&&expedition.layer()==='tunnel'){o.position.x=T.MathUtils.clamp(o.position.x+dx,-2.2,2.2);o.position.z=T.MathUtils.clamp(o.position.z+dz,-43,35);return;}if(!collides(o.position.x+dx,o.position.z,r))o.position.x+=dx;else if(o===actor?.group&&Math.abs(dx)>.02)expedition.collision();if(!collides(o.position.x,o.position.z+dz,r))o.position.z+=dz;else if(o===actor?.group&&Math.abs(dz)>.02)expedition.collision();}
function trace(origin,direction){let best=null,distance=95;
 for(const e of enemies){if(e.hp<=0)continue;const center=e.actor.group.position.clone().add(new T.Vector3(0,1.05,0));const sphere=new T.Sphere(center,.7);const p=new T.Ray(origin,direction).intersectSphere(sphere,new T.Vector3());if(p){const d=origin.distanceTo(p);if(d<distance){best=e;distance=d;}}}
 for(const c of world.colliders){const b=colliderBox(c);const p=new T.Ray(origin,direction).intersectBox(b,new T.Vector3());if(p&&origin.distanceTo(p)<distance){distance=origin.distanceTo(p);best=null;}}
 return {enemy:best,distance};
}
function tracer(from,to,color=0xe2b76e){const geo=new T.BufferGeometry().setFromPoints([from,to]);const line=new T.Line(geo,new T.LineBasicMaterial({color,transparent:true,opacity:.8}));scene.add(line);effects.push({object:line,until:elapsed+.07});}
function hitEnemy(e,damage,killer){if(!e||e.hp<=0)return;e.hp-=damage;if(e.hp<=0){e.hp=0;e.deathTime=elapsed;room.send('kill',{id:e.id,killer});if(killer===room.id)giveKill();}sendSnapshot();}
function shoot(){if(!running||modalOpen||dead||elapsed-lastShot<.145||reloadUntil>0)return;if(state.ammo<=0){reload();return;}lastShot=elapsed;shootUntil=elapsed+.18;state.ammo--;gunAudio();
 const direction=new T.Vector3();camera.getWorldDirection(direction);const origin=camera.position.clone();const hit=trace(origin,direction);const from=actor.group.position.clone().add(new T.Vector3(.25,1.35,0));tracer(from,origin.clone().addScaledVector(direction,hit.distance));muzzleLight.position.copy(from);muzzleLight.intensity=15;
 if(hit.enemy){$('#hit-marker').style.opacity='1';setTimeout(()=>$('#hit-marker').style.opacity='0',120);if(room.isHost)hitEnemy(hit.enemy,38+state.upgrade*9,room.id);}
 room.send('shoot',{origin:origin.toArray(),dir:direction.toArray(),damage:38+state.upgrade*9,from:from.toArray(),district:currentDistrict});pitch-=.003;
}
function reload(){if(reloadUntil||state.ammo>=30||state.reserve<=0||dead)return;reloadUntil=elapsed+1.6;toast('Reloading…');}
function hurt(damage){if(dead||invulnerable>elapsed||dodgeUntil>elapsed)return;audio.cue('damage');state.hp=Math.max(0,state.hp-damage*survivalBenefits(state.training).damageMultiplier);invulnerable=elapsed+.7;$('#damage').style.opacity='.5';setTimeout(()=>$('#damage').style.opacity='0',180);if(state.hp<=0)die();}
function die(){state.flood.extraction=0;dead=true;mouseDown=false;state.scrap=Math.floor(state.scrap*.7);document.exitPointerLock?.();openModal(`<span class="panel-kicker">TRANSMISSION LOST</span><h2>The night took its share.</h2><p class="panel-intro">Your rescue beacon brought you back. You lost 30% of your carried scrap, but your missions, achievements, and rank are safe.</p><div class="panel-footer"><button class="primary" data-action="respawn">Return to the relief station</button></div>`);save();}
function respawn(){expedition.resetLayer();dead=false;state.hp=100;state.hunger=Math.max(state.hunger,55);state.ammo=Math.max(state.ammo,15);state.reserve=Math.max(state.reserve,60);stamina=100;invulnerable=elapsed+6;actor.group.position.set(0,0,43);closeModal();save();}
function collect(id,player=room.id){const item=world.interact.find(i=>i.id===id);if(!item||item.used)return;
 if(item.type==='radio'){const allowed=player===room.id?state.cacheProgress[currentDistrict]>=2:true;if(!allowed){toast('Recover two relief caches before repairing the radio.');return;}item.used=true;item.marker.material=materials.blue;room.send('radio',{district:currentDistrict});finishRadio(currentDistrict);}
 else if(item.type==='cache'){item.used=true;item.group.visible=false;if(!state.depleted[currentDistrict].includes(id))state.depleted[currentDistrict].push(id);if(player===room.id)giveLoot();else room.send('lootAward',{player,id});room.send('used',{id});}sendSnapshot();
}
function giveLoot(){state.looted++;state.dailyLoot++;state.cacheProgress[currentDistrict]++;state.jobProgress++;const benefits=survivalBenefits(state.training);state.scrap+=benefits.scrap;state.reserve+=benefits.rounds;state.hunger=Math.min(100,state.hunger+12);state.xp+=20;if(state.looted%3===0)state.medkits++;toast(`Relief cache · +${benefits.rounds} rounds · +${benefits.scrap} scrap · food recovered`);if(state.jobProgress>=3){state.jobProgress-=3;state.jobs++;state.credits+=75;state.xp+=100;toast('Side job complete · Relief courier · +75 credits / +100 XP');}checkAchievements();save();}
function finishRadio(index){if(state.missions.includes(index))return;state.missions.push(index);state.xp+=200;state.credits+=100;toast('Radio restored · Return to the evacuation beacon · +200 XP');checkAchievements();save();}
function nearest(){if(!world||!actor)return null;let best=null,d=2.7;for(const i of world.interact){if(i.used&&i.type==='cache')continue;const dd=Math.hypot(actor.group.position.x-i.x,actor.group.position.z-i.z);if(dd<d){const from=actor.group.position.clone().add(new T.Vector3(0,1.2,0)),to=new T.Vector3(i.x,1.1,i.z),dir=to.clone().sub(from).normalize();const ray=new T.Ray(from,dir);if(world.colliders.some(c=>{const hit=ray.intersectBox(colliderBox(c),new T.Vector3());return hit&&hit.distanceTo(from)<dd-.15;}))continue;d=dd;best=i;}}return best;}
function interact(){if(!running||modalOpen||dead)return;const i=nearest();if(expedition.nearest()&&(!i||Math.hypot(actor.group.position.x-expedition.nearest().x,actor.group.position.z-expedition.nearest().z)<1.5)){expedition.interact();return;}if(!i)return;
 if(i.type==='bench'){showWorkshop();return;}
 if(i.type==='extract'){extract();return;}
 if(i.type==='radio'&&i.used){toast('The signal is live. Head back to the evacuation beacon.');return;}
 if(!room.isHost){if(i.type==='radio'&&state.cacheProgress[currentDistrict]<2){toast('Recover two relief caches first.');return;}room.send('interact',{id:i.id,district:currentDistrict,progress:state.cacheProgress[currentDistrict]});toast('Requesting shared supplies…');}else collect(i.id);
}
function extract(){const done=state.missions.includes(currentDistrict);if(state.lastSecured[currentDistrict]!==state.looted){state.hp=Math.min(100,state.hp+35);state.hunger=Math.min(100,state.hunger+30);state.credits+=done?25:5;state.xp+=done?30:10;state.lastSecured[currentDistrict]=state.looted;}save();openModal(`<span class="panel-kicker">EVACUATION BEACON REACHED</span><h2>${done?'A signal. A way forward.':'Back in one piece.'}</h2><p class="panel-intro">${done?'The district transmission is live. Your supplies and mission progress have been secured.':'Your scavenged supplies are secured. Recover two relief caches and repair the district radio to complete the main mission.'}</p><div class="reward-box"><div><strong>${state.kills}</strong><span>INFECTED DEFEATED</span></div><div><strong>${state.scrap}</strong><span>SCRAP SECURED</span></div><div><strong>${state.missions.length}/4</strong><span>SIGNALS RESTORED</span></div></div><div class="panel-footer"><button class="primary" data-action="map">Choose next district</button><button class="secondary" data-action="close">Keep scavenging</button></div>`);}

function openModal(html){modalOpen=true;clearInput();$('#modal-content').innerHTML=html;$('#modal').classList.remove('hidden');if(document.pointerLockElement)document.exitPointerLock();}
function closeModal(){if(dead)return;modalOpen=false;$('#modal').classList.add('hidden');}
function menu(){if(running)save();expedition.resetLayer();running=false;dead=false;closeModal();$('#menu').classList.remove('hidden');$('#hud').classList.add('hidden');$('#app').classList.remove('playing');$('#topbar').style.display='';mouseDown=false;keys.clear();if(document.pointerLockElement)document.exitPointerLock();updateDistrictUI();}
function deploy(){if(!ready)return;closeModal();running=true;$('#menu').classList.add('hidden');$('#hud').classList.remove('hidden');$('#app').classList.add('playing');actor.group.visible=true;invulnerable=elapsed+3;playAudio();toast('Click scene to capture mouse · Q shoulder · T flashlight · E scavenge');}
function showMap(){openModal(`<span class="panel-kicker">THE EVACUATION NETWORK</span><h2>Four places. One more tomorrow.</h2><p class="panel-intro">Choose an expedition. Your equipment and progress travel with you. Each district has a main transmission and repeatable relief jobs.</p><div class="district-grid">${districts.map((d,i)=>`<button class="district-card ${i===currentDistrict?'active':''}" data-travel="${i}"><span class="number">${['LA','TX','CA','LA'][i]}</span><small>${state.missions.includes(i)?'SIGNAL RESTORED':i===currentDistrict?'CURRENT EXPEDITION':'SIGNAL LOST'}</small><h3>${d.name}</h3><p>${d.tag}</p><div class="landmark">◇ ${d.landmark}</div><ul class="site-list">${siteNames[i].map(n=>`<li>${n}</li>`).join('')}</ul><small>4 ENTERABLE SITES · FOLLOW SIDE ROUTES</small></button>`).join('')}</div><div class="panel-footer"><small>${room.connected?'The room leader controls district travel for the squad.':'Travel is free. Supplies are not.'}</small></div>`);}
function showJournal(tab=activeTab){activeTab=tab;let content='';
 if(tab==='missions')content=districts.map((d,i)=>`<div class="entry"><div><h3>${d.mission}</h3><p>${d.name} · ${state.missions.includes(i)?'Transmission restored. Return to extraction.':`Recover two caches (${Math.min(2,state.cacheProgress[i])}/2), then repair the radio near ${d.landmark}.`}</p></div><span class="entry-meta ${state.missions.includes(i)?'complete':''}">${state.missions.includes(i)?'✓ COMPLETE':'+200 XP / 100 credits'}</span></div>`).join('')+`<div class="entry"><div><h3>Relief courier · Repeatable side job</h3><p>Deliver supplies by scavenging 3 relief caches. Progress ${state.jobProgress}/3 · Completed ${state.jobs} times.</p></div><span class="entry-meta">+75 credits / 100 XP</span></div>`;
 if(tab==='challenges')content=`<div class="entry"><div><h3>Hold the neighborhood</h3><p>Defeat 8 infected today · ${Math.min(8,state.dailyKills)}/8</p></div><span class="entry-meta">DAILY CHALLENGE</span></div><div class="entry"><div><h3>Leave no supplies behind</h3><p>Search 3 relief caches today · ${Math.min(3,state.dailyLoot)}/3</p></div><span class="entry-meta">DAILY CHALLENGE</span></div><div class="panel-footer"><button class="primary" data-action="challenge" ${state.dailyClaimed?'disabled':''}>${state.dailyClaimed?'Reward collected':'Claim challenge reward'}</button><small>Complete both for 150 credits and 200 XP. Resets at 00:00 UTC.</small></div>`;
 if(tab==='achievements')content=achievementList.map(a=>`<div class="entry"><div><h3>${state.achievements.includes(a.id)?'✦':'◇'} ${a.title}</h3><p>${a.desc}</p></div><span class="entry-meta ${state.achievements.includes(a.id)?'complete':''}">${state.achievements.includes(a.id)?'UNLOCKED':'LOCKED'}</span></div>`).join('');
 if(tab==='supplies')content=`<div class="reward-box"><div><strong>${state.scrap}</strong><span>SCRAP</span></div><div><strong>${state.credits}</strong><span>CREDITS</span></div><div><strong>${state.medkits}</strong><span>MEDKITS</span></div><div><strong>${state.reserve}</strong><span>SPARE ROUNDS</span></div></div><p class="panel-intro">Use a relief workbench to craft supplies and buy permanent armor, scavenging, and endurance training. Rifle upgrades improve damage permanently.</p><div class="panel-footer"><button class="primary" data-action="workshop">Open crafting</button><button class="secondary" data-action="save">Save progress</button></div>`;
 openModal(`<span class="panel-kicker">SURVIVOR ${rank()} · DAY ${state.day}</span><h2>Field journal</h2><p class="panel-intro">${state.missions.length}/4 signals restored · ${state.kills} infected defeated · ${state.xp} XP</p><div class="tabs">${['missions','challenges','achievements','supplies'].map(t=>`<button data-tab="${t}" class="${t===tab?'active':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>${content}<div class="panel-footer"><button class="secondary" data-action="map">World map</button><button class="secondary" data-action="reward">Daily supplies</button><button class="secondary" data-action="pause">Settings & controls</button></div>`);
}
function showWorkshop(){openModal(`<span class="panel-kicker">RELIEF WORKBENCH</span><h2>Make something of what's left.</h2><p class="panel-intro">Available: ${state.scrap} scrap · ${state.credits} credits. Crafted supplies are added to your pack immediately.</p><div class="entry"><div><h3>Field medkit</h3><p>Restores 55 health. Use F during an expedition.</p></div><button class="secondary" data-craft="medkit">8 scrap · Craft</button></div><div class="entry"><div><h3>Carbine ammunition</h3><p>30 spare rounds for your Ranger carbine.</p></div><button class="secondary" data-craft="ammo">6 scrap · Craft</button></div><div class="entry"><div><h3>Rifle tuning · Level ${state.upgrade}/5</h3><p>Permanent +9 damage per shot, per upgrade.</p></div><button class="secondary" data-craft="upgrade">${75+state.upgrade*50} credits · Upgrade</button></div><div class="entry"><div><h3>Emergency ration</h3><p>Restore 40 hunger and 10 health.</p></div><button class="secondary" data-craft="ration">15 credits · Buy</button></div><h3>Survival training · permanent personal upgrades</h3><p>Three levels each. Kept on death and district travel. Bonuses also apply to your personal co-op supplies.</p>${SURVIVAL_UPGRADES.map(u=>{const level=state.training[u.id],cost=trainingCost(u,level);return `<div class="entry"><div><h3>${u.name} · ${level}/3</h3><p>${u.description}</p></div><button class="secondary" data-training="${u.id}" ${level>=3||state.credits<cost?'disabled':''}>${level>=3?'Max level':`${cost} credits · Train`}</button></div>`;}).join('')}<div class="panel-footer"><button class="primary" data-action="close">Back to survival</button></div>`);}
function train(id){const next=buyTraining(state,id);if(next===state){toast('Training unavailable: check credits and max level.');return;}state=next;save();showWorkshop();toast('Survival training upgraded and saved.');}
function craft(type){if(type==='medkit'||type==='ammo'){const cost=type==='medkit'?8:6;if(state.scrap<cost){toast('Not enough scrap. Search relief caches.');return;}state.scrap-=cost;if(type==='medkit')state.medkits++;else state.reserve+=30;}
 else if(type==='upgrade'){const cost=75+state.upgrade*50;if(state.upgrade>=5){toast('Carbine fully tuned.');return;}if(state.credits<cost){toast('Not enough credits. Complete missions and side jobs.');return;}state.credits-=cost;state.upgrade++;}
 else {if(state.credits<15){toast('Not enough credits.');return;}state.credits-=15;state.hunger=Math.min(100,state.hunger+40);state.hp=Math.min(100,state.hp+10);}save();showWorkshop();toast('Supplies updated. Progress saved.');}
function showReward(){const claimed=state.lastReward===new Date().toISOString().slice(0,10);openModal(`<span class="panel-kicker">DAILY RELIEF DROP · UTC RESET</span><h2>A little help. A little hope.</h2><p class="panel-intro">The relief network hasn't forgotten you. Return each day for ammunition, medical supplies, and a few credits. Streak: ${state.streak} ${state.streak===1?'day':'days'}.</p><div class="reward-box"><div><strong>60</strong><span>CARBINE ROUNDS</span></div><div><strong>2</strong><span>MEDKITS</span></div><div><strong>50</strong><span>CREDITS</span></div></div><div class="streak">${Array.from({length:7},(_,i)=>`<span class="${i<state.streak%8?'on':''}">DAY ${i+1}</span>`).join('')}</div><div class="panel-footer"><button class="primary" data-action="claim" ${claimed?'disabled':''}>${claimed?'Supplies collected today':'Collect daily supplies'}</button><small>${claimed?'Next drop arrives at 00:00 UTC.':'No purchase needed. One claim per UTC day.'}</small></div>`);}
function claimReward(){const today=new Date().toISOString().slice(0,10);if(state.lastReward===today)return;const yesterday=new Date(Date.now()-86400000).toISOString().slice(0,10);state.streak=state.lastReward===yesterday?state.streak+1:1;state.lastReward=today;state.reserve+=60;state.medkits+=2;state.credits+=50;save();showReward();toast('Daily drop collected · +60 rounds · +2 medkits · +50 credits');}
function showPause(){openModal(`<span class="panel-kicker">TAKE A BREATH</span><h2>Survival is a long game.</h2><p class="panel-intro">WASD move · Either Shift sprint · Click scene to capture mouse · Left mouse fire · Right mouse aim · Q swap shoulder · Wheel zoom · T flashlight · R reload · E scavenge · F medkit · Space dodge · B journal · M map.<br><br>Walk through signed OPEN entrances to search furnished interiors. Side streets and boardwalks branch left and right at the route signs. Escape releases the mouse; press it again to pause. Mouse drag is available if capture is blocked. Solo panels pause enemies; co-op stays live.</p><label class="settings-row">Visual quality <select id="quality"><option value="high" ${controls.quality==='high'?'selected':''}>Cinematic</option><option value="low" ${controls.quality==='low'?'selected':''}>Performance</option></select></label><label class="settings-row">Mouse sensitivity <input id="sensitivity" type="range" min="0.3" max="2" step="0.1" value="${controls.sensitivity}"><output id="sensitivity-value">${controls.sensitivity.toFixed(1)}×</output></label><label class="settings-row"><input id="invert-look" type="checkbox" ${controls.invert?'checked':''}> Invert vertical look</label><div class="panel-footer"><button class="primary" data-action="close">Resume</button><button class="secondary" data-action="save">Save progress</button><button class="secondary" data-action="menu">Return to menu</button></div>`);}
function showCoop(){openModal(`<span class="panel-kicker">SURVIVE TOGETHER</span><h2>Better with someone watching your back.</h2><p class="panel-intro">Create or join a room, then share its code. Explore the same district, fight the same infected, and share the relief network. Personal equipment and achievements remain yours.</p>${room.connected?`<div class="big-code">${room.roomCode}</div><p class="network-note" id="room-detail">${Object.keys(room.players).length+1} survivors connected · ${room.isHost?'You lead this expedition.':'Following the room leader.'}</p><div class="panel-footer"><button class="primary" data-action="deploy">Enter expedition</button><button class="secondary" data-action="leave">Leave room</button></div>`:`<div class="coop-form"><input id="room-input" maxlength="8" placeholder="ROOM CODE" aria-label="Co-op room code"><button class="primary" data-action="join">Join room</button><button class="secondary" data-action="host">Create room</button></div><p id="network-message" class="network-note">Online co-op requires a live internet connection. Solo remains available if the service is unreachable.</p>`}<div class="panel-footer"><small>Cooperative rooms · shared enemies and loot · automatic leader recovery</small></div>`);}
async function joinRoom(code){const button=$('[data-action="join"]');if(button)button.disabled=true;const message=$('#network-message');if(message)message.textContent='Connecting to the relief network…';try{await room.join(code);showCoop();if(!room.isHost)toast('Joined expedition. Synchronizing with the leader…');}catch(e){if(message)message.textContent=e.message;toast(e.message);if(button)button.disabled=false;}}

listen($('#deploy'),'click',deploy);listen($('#audio'),'click',()=>{state.sound=!state.sound;$('#audio').textContent=state.sound?'♫':'♩';if(!state.sound)audio.suspend();if(state.sound)playAudio();save();});listen($('.brand'),'click',e=>{e.preventDefault();menu();});
listen(document,'click',e=>{const ft=e.target.closest('[data-flood-tab]');if(ft){expedition.show(ft.dataset.floodTab);return;}const fb=e.target.closest('[data-flood]');if(fb){const result=expedition.act(fb.dataset.flood);if(result?.travel!==undefined){changeDistrict(result.travel);closeModal();save();}return;}const trainingButton=e.target.closest('[data-training]');if(trainingButton)train(trainingButton.dataset.training);const district=e.target.closest('[data-district]'),travel=e.target.closest('[data-travel]'),tab=e.target.closest('[data-tab]'),craftButton=e.target.closest('[data-craft]'),action=e.target.closest('[data-action]')?.dataset.action;
 if(district&&ready){changeDistrict(+district.dataset.district);save();}
 if(travel&&ready){if(room.connected&&!room.isHost){toast('The room leader chooses district travel.');return;}changeDistrict(+travel.dataset.travel);closeModal();deploy();save();}
 if(tab)showJournal(tab.dataset.tab);if(craftButton)craft(craftButton.dataset.craft);
 if(!action)return;const actions={flood:()=>expedition.show(),menu,deploy,journal:()=>showJournal(),map:showMap,close:closeModal,reward:showReward,claim:claimReward,workshop:showWorkshop,pause:showPause,coop:showCoop,respawn,save:()=>{if(save())toast('Progress secured locally.');},host:()=>joinRoom(Math.random().toString(36).slice(2,8).toUpperCase()),join:()=>joinRoom($('#room-input')?.value||''),leave:async()=>{await room.leave();showCoop();toast('Left co-op. Solo survival active.');},challenge:()=>{if(state.dailyClaimed)return;if(state.dailyKills<8||state.dailyLoot<3){toast('Complete both daily challenges first.');return;}state.dailyClaimed=true;state.credits+=150;state.xp+=200;save();showJournal('challenges');toast('Daily challenges completed · +150 credits · +200 XP');}};actions[action]?.();
});
listen(document,'input',e=>{if(e.target.id==='sensitivity'){controls.sensitivity=Number(e.target.value);$('#sensitivity-value').textContent=`${controls.sensitivity.toFixed(1)}×`;}});
listen(document,'change',e=>{if(e.target.matches('[data-role]')){const survivor=state.flood.survivors[+e.target.dataset.role];if(survivor){survivor.station=e.target.value||null;save();}return;}if(e.target.id==='invert-look')controls.invert=e.target.checked;if(e.target.id==='quality'){controls.quality=e.target.value;const low=controls.quality==='low';renderer.setPixelRatio(low?1:Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=!low;bloom.enabled=!low;composer.setSize(innerWidth,innerHeight);toast(low?'Performance rendering enabled.':'Cinematic rendering enabled.');}});
listen(document,'keydown',e=>{if(e.target instanceof HTMLInputElement||e.target instanceof HTMLSelectElement)return; const k=e.code;if(dead&&k!=='Escape')return;if(['Space','ArrowUp','ArrowDown'].includes(k))e.preventDefault();if(e.repeat){keys.add(k);return;}
 if(k==='Escape'){if(modalOpen)closeModal();else if(running&&!document.pointerLockElement)showPause();return;}
 if(k==='KeyG'){if(running)expedition.show();return;}if(k==='KeyB'){modalOpen?closeModal():showJournal();return;}if(k==='KeyM'){modalOpen?closeModal():showMap();return;}
 if(!running||modalOpen||dead)return;keys.add(k);if(k==='KeyE')interact();if(k==='KeyR')reload();if(k==='KeyF'){if(state.medkits&&state.hp<100){state.medkits--;state.hp=Math.min(100,state.hp+55);toast('Medkit used · +55 health');save();}else toast(state.hp>=100?'Already at full health.':'No medkits. Craft one at the relief workbench.');}if(k==='Space'&&stamina>=25){dodgeUntil=elapsed+.33;stamina-=25;}if(k==='KeyL')captureMouse();if(k==='KeyQ'){controls.shoulder*=-1;toast(controls.shoulder<0?'Left shoulder camera':'Right shoulder camera');}if(k==='KeyT'){controls.flashlight=!controls.flashlight;toast(controls.flashlight?'Flashlight on':'Flashlight off');}
});listen(document,'keyup',e=>keys.delete(e.code));listen(window,'blur',clearInput);
listen(document,'visibilitychange',()=>{if(document.hidden)clearInput();});
listen($('#world'),'mousedown',e=>{if(!running||modalOpen)return;e.preventDefault();captureMouse();if(e.button===0){mouseDown=true;dragging=true;shoot();}if(e.button===2){aiming=true;dragging=true;}});listen(window,'mouseup',e=>{if(e.button===0)mouseDown=false;if(e.button===2)aiming=false;dragging=mouseDown||aiming;});listen($('#world'),'contextmenu',e=>e.preventDefault());listen(document,'mousemove',e=>{if(running&&!modalOpen&&(dragging||document.pointerLockElement)){yaw-=e.movementX*.0025*controls.sensitivity;pitch=T.MathUtils.clamp(pitch+e.movementY*.0022*controls.sensitivity*(controls.invert?-1:1),-.5,.65);}});
listen($('#world'),'wheel',e=>{if(running&&!modalOpen){e.preventDefault();controls.zoom=T.MathUtils.clamp(controls.zoom+e.deltaY*.004,2.7,7);}}, {passive:false});
listen(document,'pointerlockchange',()=>{if(!document.pointerLockElement)clearInput();});
listen(window,'resize',()=>{renderer.setSize(innerWidth,innerHeight);composer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();});

function sendSnapshot(){if(!world||!room.connected||!room.isHost)return;room.send('world',{district:currentDistrict,day:state.day,time:state.time,enemies:enemies.map(e=>({id:e.id,x:e.actor.group.position.x,z:e.actor.group.position.z,rotation:e.actor.group.rotation.y,hp:e.hp,attacking:elapsed-e.lastAttack<.7})),used:world.interact.filter(i=>i.used).map(i=>i.id)});}
function receiveSnapshot(data){if(!characters||!Number.isInteger(data.district)||!districts[data.district]||!Array.isArray(data.enemies))return;if(currentDistrict!==data.district)changeDistrict(data.district,{remote:true});state.day=data.day;state.time=data.time;applyUsed(data.used||[]);const ids=new Set();for(const d of data.enemies){if(!Number.isFinite(d.x)||!Number.isFinite(d.z))continue;ids.add(d.id);let e=enemies.find(e=>e.id===d.id);if(!e)e=makeEnemy(d.id,d.x,d.z,d.hp);if(e.hp>0&&d.hp<=0)e.deathTime=elapsed;e.hp=d.hp;e.target.set(d.x,0,d.z);e.angle=d.rotation;e.remoteAttacking=d.attacking;}for(let i=enemies.length-1;i>=0;i--)if(!ids.has(enemies[i].id)){scene.remove(enemies[i].actor.group);enemies.splice(i,1);}}
function remoteTransform(id,data){if(!characters||!Array.isArray(data.position)||data.position.some(n=>!Number.isFinite(n)))return;let remote=remotes.get(id);if(!remote){const a=characters.make('survivor');const gun=rifle(materials);gun.position.set(.2,1.3,.34);a.group.add(gun);scene.add(a.group);remote={actor:a,target:new T.Vector3(),rotation:0,data};remotes.set(id,remote);a.group.position.fromArray(data.position);}remote.target.fromArray(data.position);remote.rotation=data.rotation;remote.data=data;remote.actor.group.visible=data.district===currentDistrict&&data.active;}
const room=new CooperativeRoom({
 transform:remoteTransform,
 leave:id=>{const r=remotes.get(id);if(r)scene.remove(r.actor.group);remotes.delete(id);},
 presence:(people,host)=>{const el=$('#coop-status');el.classList.toggle('hidden',!room?.connected);if(room?.connected)el.textContent=`CO-OP ${room.roomCode}\n${people.length} survivors · ${host?'Expedition leader':'Squad member'}`;},
 status:message=>{const node=$('#network-message');if(node)node.textContent=message;},
 snapshotRequest:sendSnapshot,
 event:(type,data,sender)=>{
  if(!world||!data)return;
  const fromHost=sender===room.hostId;
  if(type==='world'&&fromHost&&!room.isHost){receiveSnapshot(data);return;}
  if(type==='shoot'&&data.district===currentDistrict&&Array.isArray(data.origin)&&Array.isArray(data.dir)&&Array.isArray(data.from)){
   const origin=new T.Vector3().fromArray(data.origin),direction=new T.Vector3().fromArray(data.dir).normalize();if(!origin.toArray().every(Number.isFinite)||!direction.toArray().every(Number.isFinite))return;
   const hit=trace(origin,direction);tracer(new T.Vector3().fromArray(data.from),origin.clone().addScaledVector(direction,hit.distance),0xa4c3b3);if(room.isHost&&hit.enemy)hitEnemy(hit.enemy,T.MathUtils.clamp(Number(data.damage)||38,1,83),sender);return;
  }
  if(type==='interact'&&room.isHost&&data.district===currentDistrict){const p=room.players[sender],item=world.interact.find(i=>i.id===data.id);if(!p||!item||!Array.isArray(p.position)||Math.hypot(p.position[0]-item.x,p.position[2]-item.z)>3.2)return;if(item.type==='radio'&&data.progress<2)return;collect(data.id,sender);return;}
  if(type==='lootAward'&&fromHost&&data.player===room.id)giveLoot();
  if(type==='used'&&fromHost){const i=world.interact.find(i=>i.id===data.id);if(i){i.used=true;i.group.visible=false;}}
  if(type==='radio'&&fromHost){finishRadio(data.district);const i=world.interact.find(i=>i.type==='radio');if(i){i.used=true;i.marker.material=materials.blue;}}
  if(type==='kill'&&fromHost&&data.killer===room.id)giveKill();
  if(type==='damage'&&fromHost&&data.player===room.id)hurt(data.amount);
 }
});

function updateEnemies(dt,active){
 for(let i=enemies.length-1;i>=0;i--){const e=enemies[i],o=e.actor.group;
  if(e.hp<=0){o.rotation.z=T.MathUtils.lerp(o.rotation.z,-Math.PI/2,Math.min(1,dt*6));o.position.y=T.MathUtils.lerp(o.position.y,-.12,Math.min(1,dt*3));if(elapsed-(e.deathTime||0)>5){scene.remove(o);enemies.splice(i,1);}continue;}
  if(!room.isHost){o.position.lerp(e.target,Math.min(1,dt*12));o.rotation.y+=T.MathUtils.euclideanModulo(e.angle-o.rotation.y+Math.PI,Math.PI*2)-Math.PI;e.actor.set(e.remoteAttacking?'attack':'zombie_walk');e.actor.mixer.update(dt);continue;}
  if(!active)continue;let target=null,targetId=room.id,distance=Infinity;
  if(running&&!dead&&expedition.layer()!=='tunnel'&&expedition.layer()!=='roof'){target=actor.group.position;distance=o.position.distanceTo(target);}
  for(const [id,p] of Object.entries(room.players)){if(!p.active||p.district!==currentDistrict||!Array.isArray(p.position)||p.hp<=0)continue;const pos=new T.Vector3().fromArray(p.position),d=o.position.distanceTo(pos);if(d<distance){target=pos;targetId=id;distance=d;}}
  if(target&&distance<28){const dx=target.x-o.position.x,dz=target.z-o.position.z;o.rotation.y=Math.atan2(dx,dz);if(distance>1.25){const speed=(state.time>=20||state.time<6?1.55:1.04)*(state.day%7===0?1.25:1);const len=Math.max(.01,Math.hypot(dx,dz));const oldX=o.position.x,oldZ=o.position.z;move(o,dx/len*speed*dt,dz/len*speed*dt,.3);if(Math.hypot(o.position.x-oldX,o.position.z-oldZ)<.001)move(o,Math.cos(o.rotation.y)*speed*dt, -Math.sin(o.rotation.y)*speed*dt,.3);e.actor.set('zombie_walk');}
   else {e.actor.set('attack');if(elapsed-e.lastAttack>1.5){e.lastAttack=elapsed;if(targetId===room.id)hurt(12);else room.send('damage',{player:targetId,amount:12});}}
  }else e.actor.set('zombie_walk');e.actor.mixer.update(dt*.85);
 }
 if(active){enemySpawnClock+=dt;const night=state.time>=20||state.time<6,blood=state.day%7===0;if(enemySpawnClock>(blood?5:night?12:25)&&enemies.filter(e=>e.hp>0).length<(blood?20:night?14:9)){enemySpawnClock=0;const z=Math.random()>.5?-42:26;makeEnemy(`horde-${Date.now()}`,currentDistrict===3?(Math.random()-.5)*4:(Math.random()-.5)*12,z);}}
}
function updateHud(){
 $('#hud-area').textContent=insideSite?`${insideSite.name.toUpperCase()} / INTERIOR`:districts[currentDistrict].area.toUpperCase();
 $('#health').textContent=Math.ceil(state.hp);$('#health-bar').style.width=`${state.hp}%`;$('#health-bar').style.background=state.hp<30?'#cb795d':'#c6cca8';$('#stamina').textContent=Math.ceil(stamina);$('#hunger').textContent=Math.ceil(state.hunger);$('#medkits').textContent=state.medkits;$('#rank').textContent=`SURVIVOR ${rank()}`;$('#xp-bar').style.width=`${state.xp%400/4}%`;$('#ammo').textContent=reloadUntil?'··':state.ammo.toString().padStart(2,'0');$('#reserve').textContent=state.reserve;
 const hours=Math.floor(state.time),mins=Math.floor(state.time%1*60);$('#clock').textContent=`DAY ${state.day} · ${String(hours).padStart(2,'0')}:${String(mins).padStart(2,'0')}`;
 $('#compass').textContent=['N','NW','W','SW','S','SE','E','NE'][Math.round(T.MathUtils.euclideanModulo(yaw,Math.PI*2)/(Math.PI/4))%8];
 const done=state.missions.includes(currentDistrict),needed=state.cacheProgress[currentDistrict]<2;$('#mission-name').textContent=districts[currentDistrict].mission;$('#mission-step').textContent=done?'Signal live. Return to the evacuation beacon.':needed?`Recover relief caches (${Math.min(2,state.cacheProgress[currentDistrict])}/2), then repair the radio.`:`Repair the radio near ${districts[currentDistrict].landmark}.`;
 const target=done?world.interact.find(i=>i.type==='extract'):needed?world.interact.filter(i=>i.type==='cache'&&!i.used).sort((a,b)=>Math.hypot(a.x-actor.group.position.x,a.z-actor.group.position.z)-Math.hypot(b.x-actor.group.position.x,b.z-actor.group.position.z))[0]:world.interact.find(i=>i.type==='radio');$('#mission-distance').textContent=target?`◇ ${Math.round(Math.hypot(target.x-actor.group.position.x,target.z-actor.group.position.z))} m · ${done?'EVACUATION':needed?'RELIEF CACHE':'RADIO RELAY'}`:'Explore another district for supplies';
 const near=nearest();$('#interact').classList.toggle('hidden',!near||modalOpen);if(near)$('#interact span').textContent=near.type==='cache'?'Search relief supplies':near.type==='radio'?(near.used?'Radio signal restored':'Repair evacuation radio'):near.type==='bench'?'Use relief workbench':'Secure supplies / extract';
 const night=state.time>=20||state.time<6;$('#threat-label').textContent=state.day%7===0?'BLOOD NIGHT · A HORDE IS COMING':night?'NIGHTFALL · INFECTED ACTIVITY RISING':'';
 drawMinimap(target);
}
function drawMinimap(target){const c=$('#minimap'),x=c.getContext('2d');x.clearRect(0,0,180,180);x.save();x.beginPath();x.arc(90,90,89,0,Math.PI*2);x.clip();x.fillStyle='#20372bc9';x.fillRect(0,0,180,180);x.strokeStyle='#d6d8ac35';x.lineWidth=1;for(let j=0;j<180;j+=30){x.beginPath();x.moveTo(j,0);x.lineTo(j,180);x.moveTo(0,j);x.lineTo(180,j);x.stroke();}const p=actor.group.position,scale=1.8;if(!state.flood.relays.includes(currentDistrict)){x.beginPath();x.arc(90,90,55,0,Math.PI*2);x.clip();}const pos=(xx,z)=>[90+(xx-p.x)*scale,90+(z-p.z)*scale];x.strokeStyle='#e3bc73aa';for(const site of world.sites){const [sx,sz]=pos(site.x-6,site.z-6);x.strokeRect(sx,sz,12*scale,12*scale);}x.fillStyle='#a8b49a35';for(const col of world.colliders){const [xx,yy]=pos(col.x-col.w/2,col.z-col.d/2);x.fillRect(xx,yy,col.w*scale,col.d*scale);}for(const i of world.interact){if(i.used&&i.type==='cache')continue;const [xx,yy]=pos(i.x,i.z);x.fillStyle=i.type==='extract'?'#e4b76e':'#b7cfad';x.fillRect(xx-2,yy-2,4,4);}for(const e of enemies){if(e.hp<=0)continue;const [xx,yy]=pos(e.actor.group.position.x,e.actor.group.position.z);x.fillStyle='#c87858';x.beginPath();x.arc(xx,yy,2.5,0,Math.PI*2);x.fill();}if(target){let [xx,yy]=pos(target.x,target.z);const dx=xx-90,dy=yy-90,l=Math.hypot(dx,dy);if(l>77){xx=90+dx/l*77;yy=90+dy/l*77;}x.strokeStyle='#ecc78c';x.strokeRect(xx-4,yy-4,8,8);}x.translate(90,90);x.rotate(-yaw);x.fillStyle='#efe5c8';x.beginPath();x.moveTo(0,-7);x.lineTo(-4,5);x.lineTo(0,3);x.lineTo(4,5);x.closePath();x.fill();x.restore();}
function updatePlayer(dt,active){if(!actor)return;let moving=false;
 if(active&&!modalOpen&&!dead){yaw-=lookStick.x*dt*2.1;pitch=T.MathUtils.clamp(pitch+lookStick.y*dt*1.3,-.5,.65);const forward=T.MathUtils.clamp((keys.has('KeyW')?1:0)-(keys.has('KeyS')?1:0)-moveStick.y,-1,1),side=T.MathUtils.clamp((keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0)+moveStick.x,-1,1);let dx=-Math.sin(yaw)*forward+Math.cos(yaw)*side,dz=-Math.cos(yaw)*forward-Math.sin(yaw)*side;const len=Math.hypot(dx,dz);const sprint=(keys.has('ShiftLeft')||keys.has('ShiftRight'))&&stamina>2&&len>0&&!aiming,dodge=dodgeUntil>elapsed;const speed=(dodge?10:sprint?6.3:aiming?2.1:3.8)*expedition.speed();if(len){const magnitude=Math.min(1,len);dx=dx/len*speed*magnitude;dz=dz/len*speed*magnitude;}velocity.lerp(new T.Vector2(dx,dz),1-Math.exp(-dt*(len?13:20)));const before=actor.group.position.clone();move(actor.group,velocity.x*dt,velocity.y*dt);moving=before.distanceToSquared(actor.group.position)>.000001;actor.group.userData.speed=moving?speed:0;if(sprint)stamina=Math.max(0,stamina-dt*survivalBenefits(state.training).sprintDrain);else stamina=Math.min(100,stamina+dt*13);
  const targetRotation=aiming||mouseDown||!len?yaw+Math.PI:Math.atan2(velocity.x,velocity.y);actor.group.rotation.y+=(T.MathUtils.euclideanModulo(targetRotation-actor.group.rotation.y+Math.PI,Math.PI*2)-Math.PI)*(1-Math.exp(-dt*16));
  if(mouseDown)shoot();if(reloadUntil&&elapsed>=reloadUntil){const fill=Math.min(30-state.ammo,state.reserve);state.ammo+=fill;state.reserve-=fill;reloadUntil=0;}
  state.hunger=Math.max(0,state.hunger-dt*.045);if(state.hunger<=0&&elapsed%2<dt)hurt(2);
 }else velocity.set(0,0);
 actor.set(elapsed<shootUntil?'shoot':moving?'run':'idle');actor.mixer.update(dt*(moving?Math.max(.65,velocity.length()/4):1));actor.group.position.y=expedition.elevation()+(dodgeUntil>elapsed?Math.sin((dodgeUntil-elapsed)/.33*Math.PI)*.18:0);
 const p=actor.group.position;insideSite=world.sites.find(s=>Math.abs(p.x-s.x)<5.8&&Math.abs(p.z-s.z)<5.8)||null;for(const s of world.sites)s.roof.visible=!(running&&insideSite===s&&camera.position.y>4.8+(currentDistrict===3?.26:0));
 if(running){const distance=aiming?2.5:controls.zoom,shoulder=(aiming?.55:.7)*controls.shoulder;const pivot=p.clone().add(new T.Vector3(0,1.55,0));const center=pivot.clone().add(new T.Vector3(Math.cos(yaw)*shoulder,0,-Math.sin(yaw)*shoulder));const desired=center.clone().add(new T.Vector3(Math.sin(yaw)*distance,.8+pitch*distance,Math.cos(yaw)*distance));const direction=desired.clone().sub(pivot).normalize();let allowed=pivot.distanceTo(desired);const ray=new T.Ray(pivot,direction);
  for(const c of expedition.layer()==='tunnel'?[]:world.colliders){const hit=ray.intersectBox(colliderBox(c,.18),new T.Vector3());if(hit)allowed=Math.min(allowed,Math.max(.55,pivot.distanceTo(hit)-.18));}
  const safe=pivot.clone().addScaledVector(direction,allowed);if(expedition.layer()==='tunnel'){safe.x=T.MathUtils.clamp(safe.x,-2.6,2.6);safe.y=Math.min(safe.y,1.25);safe.z=T.MathUtils.clamp(safe.z,-44.5,36.5);}camera.position.lerp(safe,allowed<camera.position.distanceTo(pivot)?1:1-Math.exp(-dt*12));const look=center.clone().add(new T.Vector3(-Math.sin(yaw)*20,-.4-pitch*20,-Math.cos(yaw)*20));camera.lookAt(look);camera.fov=T.MathUtils.lerp(camera.fov,aiming?46:57,1-Math.exp(-dt*9));camera.updateProjectionMatrix();
 }
 torch.visible=controls.flashlight&&running;torch.position.copy(camera.position);camera.getWorldDirection(v1);torch.target.position.copy(camera.position).addScaledVector(v1,15);
 return moving;
}
function broadcastPlayer(moving=false){if(actor&&room.connected)room.send('transform',{position:actor.group.position.toArray(),rotation:actor.group.rotation.y,moving,district:currentDistrict,hp:state.hp,active:running&&!dead});}
const networkInterval=setInterval(()=>{if(room.connected&&document.hidden){broadcastPlayer(false);if(room.isHost)sendSnapshot();}},500);
function frame(now,dt){elapsed+=dt;if(!world||!actor)return;const active=running&&!dead&&(!modalOpen||room.connected);const moving=updatePlayer(dt,active);const weather=expedition.update(dt,controls.flashlight);if(weather)scene.fog.density=weather.fog;world.root.visible=expedition.layer()!=='tunnel';
 if(!running){actor.group.visible=false;const t=elapsed*.045;camera.position.set(3.7+Math.sin(t)*.7,3.6,22);camera.lookAt(-.8,7.2,-48);camera.fov=57;camera.updateProjectionMatrix();}else actor.group.visible=true;
 updateEnemies(dt,active||room.connected);
 if((active||room.connected)&&room.isHost){state.time+=dt*.022;if(state.time>=24){state.time-=24;state.day++;state.depleted=[[],[],[],[]];state.supplyDay=state.day;applyUsed(state.missions.includes(currentDistrict)?['radio']:[]);checkAchievements();save();}}
 const daylight=state.time>=6&&state.time<20;const brightness=running?(daylight?1:.28):1;lighting.sun.intensity=T.MathUtils.lerp(lighting.sun.intensity,3.2*brightness,dt*.6);lighting.hemi.intensity=T.MathUtils.lerp(lighting.hemi.intensity,daylight||!running?1.55:.65,dt*.6);renderer.toneMappingExposure=daylight||!running?1.02:.85;
 lighting.sun.target.position.set(running?actor.group.position.x:0,0,running?actor.group.position.z:0);lighting.sun.position.set((running?actor.group.position.x:0)-35,45,(running?actor.group.position.z:0)-60);
 for(const i of world.interact)if(i.marker&&i.type!=='extract'){i.marker.rotation.y=elapsed*.7;i.marker.position.y=1.5+Math.sin(elapsed*2+i.z)*.09;}
 for(const remote of remotes.values()){remote.actor.group.visible=remote.data.active&&remote.data.district===currentDistrict;remote.actor.group.position.lerp(remote.target,Math.min(1,dt*14));remote.actor.group.rotation.y=remote.rotation;remote.actor.set(remote.data.moving?'run':'idle');remote.actor.mixer.update(dt);}
 for(let i=effects.length-1;i>=0;i--)if(elapsed>effects[i].until){const o=effects[i].object;scene.remove(o);o.geometry.dispose();o.material.dispose();effects.splice(i,1);}muzzleLight.intensity=Math.max(0,muzzleLight.intensity-dt*140);dust.rotation.y=Math.sin(elapsed*.02)*.015;
 if(room.connected){netClock+=dt;if(netClock>=1/12){netClock=0;broadcastPlayer(!!moving);}if(room.isHost&&elapsed-room.lastWorld>.2){room.lastWorld=elapsed;sendSnapshot();}}
 if(active){autosave+=dt;if(autosave>15){autosave=0;resetDaily();save();}}
 hudClock+=dt;if(hudClock>.1){hudClock=0;updateHud();}
 composer.render();
}
async function boot(){
 try{
  await initStorage(showSaveStatus);const saved=await loadSave();if(events.signal.aborted)return;if(saved&&saved.version===1){state={...defaults(),...saved};for(const k of ['missions','visited','achievements'])if(!Array.isArray(state[k]))state[k]=defaults()[k];if(!Array.isArray(state.cacheProgress)||state.cacheProgress.length!==4)state.cacheProgress=[0,0,0,0];if(state.hp<=0){state.hp=100;state.position={x:0,z:43};}}
  state.flood=restoreFlood(state.flood);state.training=restoreTraining(state.training);resetDaily();$('#load-label').textContent='Preparing the evacuation route…';characters=await loadCharacters(p=>{$('#load-bar').style.width=`${Math.round(15+p*75)}%`;});if(events.signal.aborted)return;actor=characters.make('survivor');const gun=rifle(materials);gun.position.set(.2,1.3,.34);actor.group.add(gun);scene.add(actor.group);changeDistrict(T.MathUtils.clamp(state.district,0,3),{keepPosition:true});ready=true;$('#load-bar').style.width='100%';$('#load-label').textContent='Signal established.';$('#reward-teaser').textContent=state.lastReward===new Date().toISOString().slice(0,10)?'Supplies secured. Return tomorrow.':'A little help. A little hope.';if(!state.sound)audio.suspend();if(!document.hidden)renderLoop.start();setTimeout(()=>{$('#loading').style.opacity='0';setTimeout(()=>$('#loading').classList.add('hidden'),650);},150);
 }catch(error){$('#load-label').textContent='The expedition could not load. Reload to try again.';console.error('Game initialization failed:',error.message);}
}
listen(window,'pagehide',()=>{if(ready)save();renderLoop.stop();audio.suspend();clearInput();});
listen(window,'pageshow',()=>{if(ready&&!document.hidden)renderLoop.start();});
listen(document,'visibilitychange',()=>{if(document.hidden){if(ready)save();renderLoop.stop();audio.suspend();}else if(ready)renderLoop.start();});
// Read-only state supports repeatable gameplay verification without changing progression.
window.floodStatus=()=>({survival:structuredClone(state.flood),layer:expedition.layer(),ready,running,paused:modalOpen,district:currentDistrict,position:actor?.group.position.toArray(),interior:insideSite?.name||null,sites:world?.sites.map(s=>({name:s.name,x:s.x,z:s.z,entrance:s.entrance,cache:s.cache})),controls:{...controls,yaw,pitch,aiming,velocity:velocity.toArray(),camera:camera.position.toArray()},nearest:nearest()?.id||null,hp:state.hp,ammo:state.ammo,reserve:state.reserve,kills:state.kills,looted:state.looted,missions:[...state.missions],credits:state.credits,medkits:state.medkits,day:state.day,enemies:enemies.map(e=>({id:e.id,hp:e.hp,position:e.actor.group.position.toArray()})),room:{connected:room.connected,code:room.roomCode,isHost:room.isHost,players:Object.keys(room.players).length,remotes:remotes.size},render:{calls:renderer.info.render.calls,triangles:renderer.info.render.triangles}});
joysticks.push(bindJoystick($('#move-joystick'),{listen,onChange:v=>moveStick=v,enabled:()=>running&&!modalOpen&&!dead}),bindJoystick($('#look-joystick'),{listen,onChange:v=>lookStick=v,enabled:()=>running&&!modalOpen&&!dead}));
document.querySelectorAll('[data-key]').forEach(button=>{
 listen(button,'pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);const code=button.dataset.key;if(!running||modalOpen||dead)return;if(code==='KeyE')interact();else if(code==='KeyR')reload();else if(code==='KeyT')controls.flashlight=!controls.flashlight;else keys.add(code);});
 for(const type of ['pointerup','pointercancel','lostpointercapture'])listen(button,type,()=>keys.delete(button.dataset.key));
});
listen($('#touch-fire'),'pointerdown',e=>{if(!running||modalOpen||dead)return;e.preventDefault();e.target.setPointerCapture(e.pointerId);mouseDown=true;shoot();});
for(const type of ['pointerup','pointercancel','lostpointercapture'])listen($('#touch-fire'),type,()=>mouseDown=false);
let touchLook=null;
listen($('#world'),'pointerdown',e=>{if(e.pointerType==='touch'&&running&&!modalOpen){touchLook={id:e.pointerId,x:e.clientX,y:e.clientY};e.target.setPointerCapture(e.pointerId);}});
listen($('#world'),'pointermove',e=>{if(touchLook?.id===e.pointerId){yaw-=(e.clientX-touchLook.x)*.006;pitch=T.MathUtils.clamp(pitch+(e.clientY-touchLook.y)*.004,-.5,.65);touchLook.x=e.clientX;touchLook.y=e.clientY;}});
for(const type of ['pointerup','pointercancel'])listen($('#world'),type,()=>touchLook=null);
const expedition=createExpedition({scene,getState:()=>state,getDistrict:()=>currentDistrict,getActor:()=>actor,getStamina:()=>stamina,setStamina:v=>stamina=v,hurt,move,openModal,closeModal,toast,save,isActive:()=>running&&!modalOpen&&!dead,canUse:()=>!room.connected});
const renderLoop=createRenderLoop(frame);
listen(document,'pointerdown',()=>{if(running&&!document.hidden)playAudio();});
listen(document,'keydown',()=>{if(running&&!document.hidden)playAudio();});
// Vite HMR is this vanilla game's unmount lifecycle; pagehide/pageshow support bfcache.
if(import.meta.hot)import.meta.hot.dispose(()=>{if(ready)save();events.abort();renderLoop.dispose();clearInterval(networkInterval);clearTimeout(toastTimer);clearTimeout(saveStatusTimer);audio.dispose();room.leave();expedition.dispose();disposeWorld();composer.passes.forEach(pass=>pass.dispose?.());composer.dispose();const disposed=new Set();scene.traverse(o=>{if(o.geometry&&!disposed.has(o.geometry)){o.geometry.dispose();disposed.add(o.geometry);}for(const m of Array.isArray(o.material)?o.material:o.material?[o.material]:[]){if(disposed.has(m))continue;for(const value of Object.values(m))if(value?.isTexture&&!disposed.has(value)){value.dispose();disposed.add(value);}m.dispose();disposed.add(m);}});lighting.env.dispose();renderer.dispose();delete window.floodStatus;});
boot();
